//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 	  HE_VFD_FC202_Wrapper                                                                                                                                                                                                                                                                   
//	CREATOR:	  William Veim                                                                                                                                                                                                                                                
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//  1.0.0				25.02.2025		William Veim			Draft
//===============================================================================================================================
//
//		DESCRIPTION: 
//		VFD Wrapper for Danfoss FC202 drives
//
//		FUNCTION:
//		Translates Ethernet/IP input and output asseblies for FC102 or FC202 to HE_FrekvOmf_Logic Parameters
//
//===============================================================================================================================

(*************************************************************************
 *	Update Inputs
 *************************************************************************)
 
// Config Parameter
Ext_VFD.EXT_Engineering.Auto_Visible:= 							Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=							Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=			TRUE;
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=			TRUE;
  
// Input Parmeter
FB_VFD_Logic.Cfg_ControllerTAG:=					Cfg_ControllerTAG;
FB_VFD_Logic.Cfg_ProcessTAG:=						Cfg_ProcessTAG;
FB_VFD_Logic.Inp_AutoRunFwd:=					Inp_AutoStartRef;
FB_VFD_Logic.Inp_AutoSpeedRef:=					Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_Interlock := 						Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=				Cfg_Interlock_InUse;
FB_VFD_Logic.Inp_Interlock:=							Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=				Cfg_Interlock_InUse;
FB_VFD_Logic.Cfg_STO_InUse:=						Cfg_STO_InUse;
FB_VFD_Logic.Cfg_LOTO_InUse:=					Cfg_LOTO_InUse;
FB_VFD_Logic.Inp_AlmSuppress:=					Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 			Inp_AlmSuppressDesc;
FB_VFD_Logic.Inp_ComFault :=						HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_DriveIP);

// Fieldbus Input
FB_VFD_Logic.Inp_Online :=						    Ext_VFD_Input.StatusWrd.Bit[0];
FB_VFD_Logic.Inp_Ready := 							Ext_VFD_Input.StatusWrd.Bit[1];
FB_VFD_Logic.Inp_VoltageEnabled :=				NOT Ext_VFD_Input.StatusWrd.Bit[13];
FB_VFD_Logic.Inp_RunningFwd := 					Ext_VFD_Input.StatusWrd.Bit[11];
FB_VFD_Logic.Inp_RunningRev :=					Ext_VFD_Input.StatusWrd.Bit[12];
FB_VFD_Logic.Inp_Error  := 								Ext_VFD_Input.StatusWrd.Bit[3] OR Ext_VFD_Input.StatusWrd.Bit[4];
FB_VFD_Logic.Inp_Warning := 						Ext_VFD_Input.StatusWrd.Bit[7];
FB_VFD_Logic.Inp_Remote :=							Ext_VFD_Input.StatusWrd.Bit[9];
FB_VFD_Logic.Inp_LOTO :=								NOT Ext_VFD_Input.DigitalIn.Bit[5];							
FB_VFD_Logic.Inp_STO :=								FALSE;

FB_VFD_Logic.Inp_ActSpeed := ScaleTrans(SclIn:=WORD_TO_REAL(Ext_VFD_Input.AcutalValue.Wrd),
																		  	X0:=0.0,
																		  	Y0:=0.0,
																		  	X1:=16384.0,
																		  	Y1:=100.0);

(*************************************************************************
 *	VFD Power, Current, Energy
 *************************************************************************)
 
FB_VFD_Logic.Inp_Power :=  	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.Power.Wrd)) * 0.01; // kW
FB_VFD_Logic.Inp_Current := 	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.MotorCurrent.Wrd)) * 0.01; //A
FB_VFD_Logic.Inp_Energy := 	UDINT_TO_REAL(Wrk_Energy); // kWh;
	
(*************************************************************************
 *	Runtime Statistics
 *************************************************************************)

FB_VFD_Logic.Inp_VFD_TotalOnTime:=Wrk_OperatingTime;
FB_VFD_Logic.Inp_VFD_TotalRunTime:=Wrk_RunningTime;
	
(*************************************************************************
 *	State and error
 *************************************************************************)
	
FB_VFD_Logic.Inp_Active_Error:= HE_FCx02_Drive_Fault(Inp_InverterFault := Ext_VFD_Input.AlarmWord.DWrd);
FB_VFD_Logic.Inp_Active_Warning:= ''; //NOT IN USE
FB_VFD_Logic.Inp_Actual_State:=	HE_FCx02_Drive_State(Inp_InverterStatus:=Ext_VFD_Input.StatusWrd.Wrd, Inp_ReverseRunning:=Ext_VFD.EXT_Engineering.ReverseRunning_Start);

(*************************************************************************
 *	Execute Explicit message block
 *************************************************************************)
 
FB_VFD_ExplicitMessage(ENS:=TRUE, 
											Ext_Telegram:=Ext_Telegram, 
											Cfg_RoutePath:=Cfg_RoutePath, 
											Val_OperatingTime=>Wrk_OperatingTime, 
											Val_RunningTime=>Wrk_RunningTime, 
											Val_EnergyCounter=>Wrk_Energy);	

(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
							Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Update Outputs
 *************************************************************************)

//Activate reverse bit, delay before start
TON_ReverseStart(In:=FB_VFD_Logic.Out_RunRev, PT:=TIME#5s);

// Output Parameters
Sts_Alarm:=					FB_VFD_Logic.Sts_AlarmTriggered;
Sts_AvailableAuto := 	FB_VFD_Logic.Sts_AvailableAuto;
Sts_Interlock := 			FB_VFD_Logic.Sts_Interlock;
Sts_RunningFwd :=	 	FB_VFD_Logic.Inp_RunningFwd;

// Fieldbus Output
Ext_VFD_Output.FB_ControlWrd.Bit[0] := 			FALSE; //Use reference value
Ext_VFD_Output.FB_ControlWrd.Bit[1] := 			FALSE; //Use reference value
Ext_VFD_Output.FB_ControlWrd.Bit[2] := 			TRUE; //Use ramp
Ext_VFD_Output.FB_ControlWrd.Bit[4] := 			TRUE; //Use ramp
Ext_VFD_Output.FB_ControlWrd.Bit[5] := 			TRUE; //Use ramp
Ext_VFD_Output.FB_ControlWrd.Bit[10] := 			TRUE; //Data valid
Ext_VFD_Output.FB_ControlWrd.Bit[3] := 			FB_VFD_Logic.Out_Enable; //No coasting
Ext_VFD_Output.FB_ControlWrd.Bit[6] := 			FB_VFD_Logic.Out_RunFwd OR TON_ReverseStart.Q; // Cmd start running
Ext_VFD_Output.FB_ControlWrd.Bit[15]:=			FB_VFD_Logic.Out_RunRev; // Cmd start reverse running
Ext_VFD_Output.FB_ControlWrd.Bit[7]:= 			FB_VFD_Logic.Out_FaultReset; // Fault Reset
Ext_VFD_Output.FB_Ramp1_UpTime.Wrd:= 		UINT_TO_WORD(Ext_VFD.EXT_Engineering.LCfg_RampUpTime*100); //Ramp up time
Ext_VFD_Output.FB_Ramp1_DownTime.Wrd:= 	UINT_TO_WORD(Ext_VFD.EXT_Engineering.LCfg_RampDownTime*100); //Ramp down time

Ext_VFD_Output.FB_Reference.Wrd:= REAL_TO_WORD(ScaleTrans(SclIn:=FB_VFD_Logic.Out_SpeedRef,
																												X0:=0.0,
																												Y0:=0.0,
																												X1:=100.0,
																												Y1:=16384.0));
